#include <iostream>

struct CantidadInvalida {};
struct SumaExcesiva {};

class Cantidad {
public:
    Cantidad() = default;
    explicit Cantidad(int valor) : unidades_{valor} {
        if (valor < 0 || valor > 1000) { throw CantidadInvalida{}; }
    }
    int valor() const noexcept { return unidades_; }
    Cantidad operator+(const Cantidad& otra) const;
    Cantidad& operator+=(const Cantidad& otra);
private:
    int unidades_ = 0;
};
Cantidad Cantidad::operator+(const Cantidad& otra) const {
    const int suma = unidades_ + otra.unidades_;
    if (suma > 1000) { throw SumaExcesiva{}; }
    return Cantidad{suma};
}
Cantidad& Cantidad::operator+=(const Cantidad& otra) {
    *this = *this + otra;
    return *this;
}
Cantidad operator+(const Cantidad& cantidad, int entero) {
    // Valida el entero, realiza la suma y devuelve otra Cantidad.
    (void)entero;
    return cantidad;
}

Cantidad operator+(int entero, const Cantidad& cantidad) {
    // Conserva el mismo contrato con el entero a la izquierda.
    (void)entero;
    return cantidad;
}
int main() {
    int ordenes = 0;
    if (!(std::cin >> ordenes) || ordenes < 1 || ordenes > 12) { return 1; }
    Cantidad valores[3]{Cantidad{400}, Cantidad{100}, Cantidad{90}};
    for (int i = 0; i < ordenes; ++i) {
        int op = 0, destino = 0, origen = 0, entero = 0;
        if (!(std::cin >> op >> destino >> origen >> entero)) { return 1; }
        std::cout << "Antes:" << valores[0].valor() << ':' << valores[1].valor() << ':' << valores[2].valor();
        const char* estado = "Operacion";
        if (op >= 1 && op <= 3) {
            if (destino < 0 || destino > 2 || (op != 1 && (origen < 0 || origen > 2))) {
                estado = "Indice";
            } else {
                try {
                    if (op == 1) { valores[destino] = Cantidad{entero}; }
                    else if (op == 2) { valores[destino] = valores[origen] + entero; }
                    else { valores[destino] = entero + valores[origen]; }
                    estado = "Aceptada";
                } catch (const CantidadInvalida&) { estado = "Rango"; }
                  catch (const SumaExcesiva&) { estado = "Suma"; }
            }
        }
        std::cout << ";Estado:" << estado << ";Ahora:" << valores[0].valor() << ':' << valores[1].valor() << ':' << valores[2].valor() << '\n';
    }
    std::cout << "Final:" << valores[0].valor() << ':' << valores[1].valor() << ':' << valores[2].valor();
    return 0;
}

